   Set<?> vertices=new LinkedHashSet<>((Set<?>)call(call(system,"getSig"),"vertexSet")),edges=new LinkedHashSet<>((Set<?>)call(call(system,"getSig"),"edgeSet"));Inter result=super.create(eval,glyph,staff);row.put("returns_null",result==null);row.put("result",result==null?null:readTuplet(system,result));if(result==null){Set<?> afterV=(Set<?>)call(call(system,"getSig"),"vertexSet"),afterE=(Set<?>)call(call(system,"getSig"),"edgeSet");row.put("vertex_edge_identity_retained",vertices.size()==afterV.size()&&edges.size()==afterE.size()&&vertices.stream().allMatch(x->containsIdentity(afterV,x))&&edges.stream().allMatch(x->containsIdentity(afterE,x)));}candidates.add(row);return result;
